-- Public editorial research records; administrator-only writes.
create table public.political_events (
  slug text primary key check (slug ~ '^[a-z0-9-]+$'),
  title text not null,
  event_type text not null check (event_type in ('consultation','policy_announcement','legislation','statistics_release')),
  policy_area text not null,
  jurisdiction text not null,
  policy_status text not null check (policy_status in ('proposal','announced','enacted','in_force','withdrawn')),
  event_date date not null,
  source_url text not null references public.source_documents(source_url),
  record jsonb not null check (jsonb_typeof(record) = 'object'),
  created_at timestamptz not null default now()
);
create table public.sectors (
  slug text primary key,
  name text not null
);
create table public.event_sector_impacts (
  id text primary key,
  event_slug text not null references public.political_events(slug),
  sector_slug text not null references public.sectors(slug),
  mechanism text not null check (mechanism in ('demand_incentive','compliance_cost','investment_incentive')),
  direction text not null check (direction in ('supportive','adverse','mixed','uncertain')),
  confidence text not null check (confidence in ('low','medium','high')),
  assessment jsonb not null check (jsonb_typeof(assessment) = 'object')
);
create index event_sector_impacts_event_idx on public.event_sector_impacts(event_slug);
create index event_sector_impacts_sector_idx on public.event_sector_impacts(sector_slug);
create index political_events_source_idx on public.political_events(source_url);
alter table public.political_events enable row level security;
alter table public.sectors enable row level security;
alter table public.event_sector_impacts enable row level security;
revoke all on public.political_events, public.sectors, public.event_sector_impacts from anon, authenticated;
grant select on public.political_events, public.sectors, public.event_sector_impacts to anon, authenticated;
create policy "Read public events" on public.political_events for select to anon, authenticated using (true);
create policy "Read public sectors" on public.sectors for select to anon, authenticated using (true);
create policy "Read public impact assessments" on public.event_sector_impacts for select to anon, authenticated using (true);

