with entry as (select '{"slug": "clean-heat-2027", "title": "Clean Heat: higher targets, wider flexibility", "event_type": "consultation", "policy_area": "Energy", "jurisdiction": "United Kingdom", "policy_status": "proposal", "event_date": "2026-10-12", "source_updated_at": "2026-10-19", "checked_at": "2026-10-20", "source_url": "https://www.gov.uk/government/consultations/clean-heat-market-mechanism-revisions-ahead-of-the-202728-scheme-year", "document_url": "https://assets.publishing.service.gov.uk/media/6ad247a4dfa45fcb6753cb45/CHMM_Year_3_consultation_document_V4_-_8th_Nov__16_October_update_.pdf", "document_sha256": "f63d906d101d3bb4a69f5d951166b5fe9c8af88987b61606d6451f3e2bbf5981", "deadline": "2026-11-08T23:59:00Z", "summary": "DESNZ is consulting on higher heat-pump credit targets for 2027/28–2030/31, an extension of the scheme to March 2032 and more flexibility for manufacturers. This is a proposed revision to an existing scheme, not a newly enacted obligation.", "authorship": "AI-assisted worked example, checked against the cited consultation. Not an automated model output or an independently reviewed assessment.", "review_status": "awaiting_independent_review", "facts": [{"id": "F1", "statement": "The consultation describes the existing 2026/27 target as 8% of eligible boiler sales and proposes targets of 9%, 12%, 15% and 18% for 2027/28 through 2030/31. These percentages define credit obligations relative to relevant sales; they are not heat-pump market-share forecasts.", "page": 7}, {"id": "F2", "statement": "The proposed regulatory extension runs to 31 March 2032. Targets in this consultation stop at 2030/31; the additional 2031/32 year would need a target set later.", "page": 8}, {"id": "F3", "statement": "Eligible, MCS-certified heat-pump installations in new buildings would generate credits from 2027/28. The proposed targets do not assume a fixed contribution from new-build completions.", "page": 9}, {"id": "F4", "statement": "DESNZ proposes retaining the ability to carry forward up to 35% of a target and retaining existing credit carryover arrangements. Target carry-forward and credit carryover are different flexibilities.", "page": 10}, {"id": "F5", "statement": "DESNZ proposes keeping the payment-in-lieu at £500 for each missing credit in scheme years 3–6. It also proposes continuing to exclude air-to-air heat pumps and heat batteries at this stage.", "page": 11}, {"id": "F6", "statement": "A proposed supply-chain plan could award qualifying participants 10,000 credits once. DESNZ is considering £10m of new UK manufacturing investment as one qualifying route, with maintained SBTi enrolment as an alternative. These are proposals, not an awarded subsidy or a guaranteed investment commitment.", "page": 13}, {"id": "F7", "statement": "The consultation applies across the United Kingdom and asks for responses by 8 November 2026.", "page": 5}], "targets": [{"year": "2026/27", "percentage": 8, "status": "Existing — as described by DESNZ", "page": 7}, {"year": "2027/28", "percentage": 9, "status": "Proposed", "page": 7}, {"year": "2028/29", "percentage": 12, "status": "Proposed", "page": 7}, {"year": "2029/30", "percentage": 15, "status": "Proposed", "page": 7}, {"year": "2030/31", "percentage": 18, "status": "Proposed", "page": 7}], "watchpoints": ["Consultation response and final regulations: which targets and flexibilities survive?", "Credit supply from new builds, carryover and any investment-related credits: how much extra installation demand remains?", "Household uptake, installer capacity and manufacturer credit positions: can supply respond profitably?", "Company filings: establish UK heat-pump activity, regulatory scope and material revenue exposure before naming beneficiaries."]}'::jsonb as v)
